package com.bplus.share;
import android.app.*;import android.media.*;import android.net.Uri;import android.os.*;import android.view.Gravity;import android.widget.*;import java.util.*;
public final class VoicePlayer{
 private static final WeakHashMap<Activity,ArrayList<MediaPlayer>> active=new WeakHashMap<>();
 public static void release(Activity a){ArrayList<MediaPlayer> players=active.remove(a);if(players!=null)for(MediaPlayer p:players)try{p.release();}catch(Exception ignored){}}
 static String time(int ms){return String.format(java.util.Locale.US,"%d:%02d",ms/60000,ms/1000%60);}
 public static android.view.View view(Activity a,Uri uri,int ink){LinearLayout col=Ui.col(a),row=Ui.row(a);TextView play=Ui.t(a,"▶",24,ink,App.cairoB);play.setGravity(Gravity.CENTER);play.setContentDescription(a.getString(R.string.voice_play));row.addView(play,Ui.lp(Ui.dp(a,44),Ui.dp(a,48)));SeekBar seek=new SeekBar(a);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(ink));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(ink));row.addView(seek,Ui.lpw(1));col.addView(row,Ui.lp(Ui.dp(a,238),-2));TextView clock=Ui.t(a,"0:00",12,ink,App.cairoSB);col.addView(clock);MediaPlayer player=new MediaPlayer();ArrayList<MediaPlayer> players=active.get(a);if(players==null){players=new ArrayList<>();active.put(a,players);}players.add(player);final boolean[] ready={false},dead={false},loading={false};Handler h=new Handler();Runnable update=new Runnable(){public void run(){if(dead[0]||a.isFinishing()||a.isDestroyed())return;try{if(ready[0]){seek.setProgress(player.getCurrentPosition());clock.setText(time(player.getCurrentPosition())+" / "+time(player.getDuration()));}h.postDelayed(this,300);}catch(Exception ignored){}}};try{player.setDataSource(a,uri);player.setOnPreparedListener(p->{ready[0]=true;p.start();play.setText("❚❚");seek.setMax(p.getDuration());clock.setText("0:00 / "+time(p.getDuration()));h.post(update);});player.setOnCompletionListener(p->{play.setText("▶");seek.setProgress(0);});player.setOnErrorListener((p,what,extra)->{dead[0]=true;clock.setText(R.string.voice_play_failed);return true;});}catch(Exception e){dead[0]=true;clock.setText(R.string.voice_play_failed);}play.setOnClickListener(v->{if(dead[0])return;if(!ready[0]){if(!loading[0])try{loading[0]=true;player.prepareAsync();}catch(Exception ignored){}return;}try{if(player.isPlaying()){player.pause();play.setText("▶");}else{player.start();play.setText("❚❚");}}catch(Exception ignored){}});seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int progress,boolean user){if(user&&ready[0])try{player.seekTo(progress);}catch(Exception ignored){}}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});return col;}
}
